using SparkFlow.Server.Application.Abstractions.Persistence; using SparkFlow.Server.Application.Services; using SparkFlow.Server.Domain.Entities; using SparkFlow.Server.Domain.Enums; namespace SparkFlow.Server.Application.Features.Workers.RequestSession; public sealed class RequestSessionHandler { private readonly IWorkerRepository _workers; private readonly ISessionRepository _sessions; private readonly IAccountRepository _accounts; private readonly IFlowRepository _flows; private readonly SchedulerService _scheduler; public RequestSessionHandler(IWorkerRepository workers, ISessionRepository sessions, IAccountRepository accounts, IFlowRepository flows, SchedulerService scheduler){_workers=workers;_sessions=sessions;_accounts=accounts;_flows=flows;_scheduler=scheduler;} public async Task<(Session? Session, Account? Account, FlowEnvelope? Flow)> Handle(RequestSessionCommand command, CancellationToken cancellationToken=default){ var worker = await _workers.GetByIdAsync(command.WorkerId,cancellationToken); if(worker is null || !worker.IsIdle()) return (null,null,null); var session = (await _sessions.ListAsync(cancellationToken)).Where(s=>s.Status==SessionStatus.Assigned && s.WorkerId?.Value==command.WorkerId).OrderBy(s=>s.CreatedAtUtc).FirstOrDefault(); if(session is null){ session = await _scheduler.ScheduleOnceAsync(cancellationToken); if(session is null || session.WorkerId?.Value != command.WorkerId) return (null,null,null);} var account = await _accounts.GetByIdAsync(session.AccountId.Value,cancellationToken); var flow = _flows.Get(session.FlowId); return (session, account, flow); } }
